-- template-config:end
  'Atelier v1: centered crest header, 7 home sections, The house, Contact and FAQ pages, centered links footer'
FROM templates t
WHERE t.key = 'atelier'
ON CONFLICT (template_id, version) DO NOTHING;

UPDATE templates t SET current_version_id = v.id, updated_at = now()
FROM template_versions v
WHERE t.key = 'atelier' AND v.template_id = t.id AND v.version = 1
  AND t.current_version_id IS DISTINCT FROM v.id;

-- Rollback: DELETE FROM templates WHERE key = 'atelier'; (cascades to its versions and installs).
